import sys,json,time,shutil
import numpy as np
from scipy import sparse
from scipy.optimize import lsq_linear
from baseline_registry import ROOT,REPO,ref,dump,sha

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);q=p['q'];lo=p['lower'];hi=p['upper'];eq=np.isfinite(hi)&(lo==hi);ineq=~eq;ee=np.flatnonzero(eq);ray=np.load(REPO/s['source_ray']['path']);records=[];previous=None;checks=dict(all_original_rows=A.shape==(2208,72231),no_physical_springs=s['physical_regularization']==0,no_physical_update=s['actual_support_updates']==0,source_field_unchanged=sha(REPO/s['source_field']['path'])==s['source_field']['SHA256']);last=None
 def obj(x):return float(.5*x@(P@x)+q@x)
 for row in s['batches']:
  c=np.load(REPO/row['output']['path']);x=c['before_x'];dx=c['direction_physical'];new=c['after_x'];ys=c['projection_dual'];end=A@(x+dx)-lo;sn=A@new-lo;pr=max(float(np.max(np.maximum(-end[ineq],0))),float(np.max(abs(end[eq]))));sign=float(np.max(np.maximum(ys[ineq],0)));comp=float(np.max(abs(end[ineq]*ys[ineq])));gt=float((P@x+q)@dx);curv=float(dx@(P@dx));alpha=min(1.,-gt/curv) if gt<0 and curv>0 else 1.;expected=x+alpha*dx;es=A@expected-lo;epr=max(float(np.max(np.maximum(-es[ineq],0))),float(np.max(abs(es[eq]))));accepted=pr<1e-10 and sign<1e-8 and comp<1e-8 and gt<0 and epr<1e-10 and obj(expected)<=obj(x)+1e-4*alpha*gt;violated=np.flatnonzero(ineq&(end<-1e-10));newrows=np.setdiff1d(violated,c['active']);local=dict(hash=sha(REPO/row['output']['path'])==row['output']['SHA256'],same_audited_ray=np.max(abs(c['desired_direction']-ray['direction_physical']))==0,same_audited_source_x=np.max(abs(x-ray['before_x']))==0,all_endpoint_slacks_reproduced=np.max(abs(end-c['endpoint_slack_mm']))<1e-12,all_after_slacks_reproduced=np.max(abs(sn-c['after_slack_mm']))<1e-12,primal_reproduced=abs(pr-row['finite_endpoint_primal_mm'])<1e-12,sign_reproduced=abs(sign-row['projection_dual_sign_N'])<1e-10,complementarity_reproduced=abs(comp-row['projection_complementarity_Nmm'])<1e-10,objective_direction_reproduced=abs(gt-row['physical_directional_objective_Nmm'])<1e-12,curvature_reproduced=abs(curv-row['physical_curvature_Nmm'])<1e-12,alpha_reproduced=abs(alpha-row['accepted_alpha'])<1e-12,acceptance_reproduced=accepted==row['accepted_linear_step'],all_violated_original_rows_reproduced=violated.tolist()==row['violated_original_rows'],all_batch_add_rows_reproduced=newrows.tolist()==row['batch_add_original_rows'])
  if accepted:local.update(feasible_actual_state=epr<1e-10,physical_objective_decreases=obj(new)<obj(x),accepted_state_reproduced=np.max(abs(new-expected))<1e-12,reverse_descent_ray_rejected=-gt>0)
  else:local['rejected_not_applied']=np.max(abs(new-x))==0
  if previous is not None:local['batch_transition_reproduced']=np.array_equal(np.union1d(previous['active'],previous['newrows']),c['active'])
  desired_sl=A@(x+c['desired_direction'])-lo;bad=int(np.argmin(np.where(ineq,desired_sl,np.inf)));local['omitting_finite_gap_projection_rejected']=desired_sl[bad]<-1e-10
  # All generated cone variables, including gauges, enter exact small dual KKT.
  v=c['small_y'];grad=c['small_S']@v-c['small_h'];mask=ineq[c['active']];free=(~mask)|(v<-1e-8);smallk=max(float(np.max(abs(grad[free]))) if np.any(free) else 0.,float(np.max(np.maximum(grad[mask&(~free)],0))) if np.any(mask&(~free)) else 0.);checks['batch'+str(row['batch'])]=all(local.values());ev,eu=np.linalg.eigh(c['small_S']);cut=max(ev[-1]*1e-12,1e-15);null_h=float(np.max(abs(eu[:,ev<=cut].T@c['small_h']))) if np.any(ev<=cut) else 0.;records.append(dict(small_eigenvalue_min=float(ev[0]),small_eigenvalue_max=float(ev[-1]),small_numerical_rank_1e12=int(np.sum(ev>cut)),small_nullspace_rhs_component=null_h,batch=row['batch'],checks={k:bool(vv) for k,vv in local.items()},finite_primal_mm=pr,projection_complementarity_Nmm=comp,objective_change_Nmm=obj(new)-obj(x),small_dual_KKT=smallk,unprojected_worst_original_row=bad,unprojected_slack_mm=float(desired_sl[bad]),accepted_linear_step=bool(accepted)));previous=dict(active=c['active'],newrows=newrows);last=new
 # Independently recover PHYSICAL multipliers at final LINEAR trial, not search duals.
 if last is not None:
  sl=A@last-lo;active=np.union1d(ee,np.flatnonzero(ineq&(abs(sl)<1e-10)));Ar=A[active].T.toarray();force=P@last+q;rec=lsq_linear(Ar,-force,bounds=(np.full(len(active),-np.inf),np.where(ineq[active],0.,np.inf)),method='bvls',tol=1e-13,max_iter=200,lsq_solver='exact');y=np.zeros(len(lo));y[active]=rec.x;res=force+A.T@y;physical=dict(primal_mm=max(float(np.max(np.maximum(-sl[ineq],0))),float(np.max(abs(sl[eq])))),stationarity_N=float(np.max(abs(res))),complementarity_Nmm=float(np.max(abs(sl[ineq]*y[ineq]))),sign_N=float(np.max(np.maximum(y[ineq],0))),gauge_N=float(np.max(abs(y[ee]))),RootY_gamma_stationarity_N=float(abs(y[2175])));physical['qualified']=all(v<1e-8 for v in physical.values());np.savez_compressed(out/'physical_cone_recovery.npz',linear_trial_x=last,physical_dual=y,physical_residual_N=res,physical_slack_mm=sl,active=active);physical['output']=ref(out/'physical_cone_recovery.npz');physical['solver_status']=int(rec.status);physical['scope']='Best computed local physical cone recovery at the original-source LINEAR trial; not nonlinear equilibrium or an impossibility proof.'
 else:physical=None
 cad=json.loads((ROOT/'cad/exports/primaryP1_seated22/summary.json').read_text());checks['78actualCADhashes']=len(cad['part_references'])==78 and all(sha(REPO/r['path'])==r['SHA256'] for r in cad['part_references'].values());result=dict(status='ACTUAL_P1_FINITE_GAP_PROJECTION_INDEPENDENT_AUDIT_PASS' if all(checks.values()) else 'ACTUAL_P1_FINITE_GAP_PROJECTION_INDEPENDENT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},batches=records,independent_physical_KKT=physical,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start,limitations=['Audit verifies actual all-row finite-step acceptance/rejection, not product release. Search projection duals and independently recovered physical multipliers are different quantities.','No changed product solids or nonlinear support state. Material/source/mesh/physicalanchor/full3DFinger/finitewire/friction/protector/globalenergy/full3Finger remain unqualified.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if all(checks.values()) else 2)
if __name__=='__main__':main()
